{
  "name": "DG1000Z函数/任意波形发生器",
  "name_en": "DG1000Z Function/Arbitrary Waveform Generator",
  "manufacturer": "Rigol",
  "description": "这是一台台式函数/任意波形发生器，用于输出正弦波、脉冲、直流和任意波形等电信号，并支持突发输出等模式。它常用于电子学实验、仪器联调、电路激励、时序与脉冲测试以及传感器或控制系统的信号模拟。",
  "description_en": "This is a benchtop function/arbitrary waveform generator used to produce electrical test signals such as standard waveforms, pulses, DC levels, and arbitrary waveforms, with support for burst output modes. It is commonly used in electronics labs for circuit stimulation, instrument testing, timing and pulse experiments, and signal emulation for sensors or control systems.",
  "actions": [
    {
      "action_name": "auto-burst_trigger_now",
      "description": "立即触发指定通道的突发输出",
      "description_en": "Trigger burst output immediately on the selected channel"
    },
    {
      "action_name": "auto-query_channel_enabled",
      "description": "查询指定通道是否启用输出",
      "description_en": "Query whether the selected channel output is enabled"
    },
    {
      "action_name": "auto-query_waveform",
      "description": "查询指定通道的波形设置",
      "description_en": "Query the waveform configuration of the selected channel"
    },
    {
      "action_name": "auto-set_arb_mode",
      "description": "设置指定通道的任意波形模式",
      "description_en": "Set the arbitrary waveform mode of the selected channel"
    },
    {
      "action_name": "auto-set_arb_samplerate",
      "description": "设置指定通道任意波形的采样率",
      "description_en": "Set the arbitrary waveform sample rate of the selected channel"
    },
    {
      "action_name": "auto-set_burst_delay",
      "description": "设置指定通道突发输出的延迟",
      "description_en": "Set the burst delay of the selected channel"
    },
    {
      "action_name": "auto-set_burst_enabled",
      "description": "设置指定通道是否启用突发模式",
      "description_en": "Set whether burst mode is enabled on the selected channel"
    },
    {
      "action_name": "auto-set_burst_mode",
      "description": "设置指定通道的突发模式",
      "description_en": "Set the burst mode of the selected channel"
    },
    {
      "action_name": "auto-set_burst_ncycles",
      "description": "设置指定通道突发输出的循环数",
      "description_en": "Set the burst cycle count of the selected channel"
    },
    {
      "action_name": "auto-set_burst_period",
      "description": "设置指定通道突发输出的周期",
      "description_en": "Set the burst period of the selected channel"
    },
    {
      "action_name": "auto-set_burst_trigger_source",
      "description": "设置指定通道突发输出的触发源",
      "description_en": "Set the burst trigger source of the selected channel"
    },
    {
      "action_name": "auto-set_channel_arbitrary",
      "description": "将指定通道设置为任意波形输出",
      "description_en": "Set the selected channel to arbitrary waveform output"
    },
    {
      "action_name": "auto-set_channel_dc",
      "description": "将指定通道设置为直流输出电平",
      "description_en": "Set the selected channel to DC output"
    },
    {
      "action_name": "auto-set_channel_enabled",
      "description": "设置指定通道是否启用输出",
      "description_en": "Set whether the selected channel output is enabled"
    },
    {
      "action_name": "auto-set_channel_waveform",
      "description": "设置指定通道的波形类型",
      "description_en": "Set the waveform type of the selected channel"
    },
    {
      "action_name": "auto-set_high_voltage_level",
      "description": "设置指定通道的高电平电压",
      "description_en": "Set the high voltage level of the selected channel"
    },
    {
      "action_name": "auto-set_low_voltage_level",
      "description": "设置指定通道的低电平电压",
      "description_en": "Set the low voltage level of the selected channel"
    },
    {
      "action_name": "auto-set_pulse_frequency",
      "description": "设置指定通道脉冲波形的频率",
      "description_en": "Set the pulse frequency of the selected channel"
    },
    {
      "action_name": "auto-set_pulse_period",
      "description": "设置指定通道脉冲波形的周期",
      "description_en": "Set the pulse period of the selected channel"
    },
    {
      "action_name": "auto-set_pulse_width",
      "description": "设置指定通道脉冲波形的宽度",
      "description_en": "Set the pulse width of the selected channel"
    },
    {
      "action_name": "auto-set_volatile_waveform",
      "description": "设置指定通道的易失性任意波形",
      "description_en": "Set a volatile arbitrary waveform on the selected channel"
    },
    {
      "action_name": "auto-set_voltage_levels",
      "description": "设置指定通道的高低电平电压",
      "description_en": "Set the high and low voltage levels of the selected channel"
    }
  ],
  "tag_hints": [
    "function generator",
    "arbitrary waveform generation",
    "pulse generation",
    "burst mode",
    "electronic test signals",
    "bench instrumentation"
  ]
}

